#include <zephyr/kernel.h>
#include <zephyr/sys/hash_map.h>
#include <zephyr/sys/util.h>
#include <zephyr/sys/math_extras.h>

static uint32_t hash_func(uint64_t key)
{
	return sys_hash64(key);
}

static struct sys_hash_map_entry *get_free_entry(struct sys_hash_map *map)
{
	struct sys_hash_map_entry *entry = map->free_list;

	if (entry) {
		map->free_list = entry->next;
	}

	return entry;
}

static void put_free_entry(struct sys_hash_map *map,
			   struct sys_hash_map_entry *entry)
{
	entry->next = map->free_list;
	map->free_list = entry;
}

int sys_hash_map_init(struct sys_hash_map *map, uint32_t max_entries,
		      struct sys_hash_map_entry *entry_array)
{
	if (map == NULL || max_entries == 0 || entry_array == NULL) {
		return -EINVAL;
	}

	map->n_entries = max_entries;

	/*
	 * Number of buckets must be a power of 2 for the modulo arithmetic
	 * to work. Round up to the next power of 2.
	 */
	map->n_buckets = (max_entries == 1) ? 1 : 1 << find_msb_set(max_entries - 1);

	map->buckets = k_malloc(map->n_buckets * sizeof(struct sys_hash_map_entry *));
	if (map->buckets == NULL) {
		return -ENOMEM;
	}

	(void)memset(map->buckets, 0,
		     map->n_buckets * sizeof(struct sys_hash_map_entry *));

	map->free_list = NULL;
	for (int i = max_entries - 1; i >= 0; i--) {
		entry_array[i].next = map->free_list;
		map->free_list = &entry_array[i];
	}

#ifdef CONFIG_SYS_HASH_MAP_LOCK
	k_mutex_init(&map->lock);
#endif

	return 0;
}

int sys_hash_map_insert(struct sys_hash_map *map, uint64_t key, void *value,
			void **old_value)
{
	uint32_t hash = hash_func(key);
	uint32_t bucket_idx = hash & (map->n_buckets - 1);
	struct sys_hash_map_entry *entry;

	SYS_HASH_MAP_LOCK(map);

	entry = map->buckets[bucket_idx];

	while (entry) {
		if (entry->key == key) {
			break;
		}
		entry = entry->next;
	}

	if (entry) {
		if (old_value) {
			*old_value = entry->value;
		}
		entry->value = value;
		SYS_HASH_MAP_UNLOCK(map);
		return 1;
	}

	entry = get_free_entry(map);
	if (!entry) {
		SYS_HASH_MAP_UNLOCK(map);
		return -ENOMEM;
	}

	entry->key = key;
	entry->value = value;
	entry->next = map->buckets[bucket_idx];
	map->buckets[bucket_idx] = entry;

	SYS_HASH_MAP_UNLOCK(map);

	return 0;
}

int sys_hash_map_remove(struct sys_hash_map *map, uint64_t key, void **value)
{
	uint32_t hash = hash_func(key);
	uint32_t bucket_idx = hash & (map->n_buckets - 1);
	struct sys_hash_map_entry *entry, *prev = NULL;

	SYS_HASH_MAP_LOCK(map);

	entry = map->buckets[bucket_idx];

	while (entry) {
		if (entry->key == key) {
			break;
		}
		prev = entry;
		entry = entry->next;
	}

	if (!entry) {
		SYS_HASH_MAP_UNLOCK(map);
		return -ENOENT;
	}

	if (prev) {
		prev->next = entry->next;
	} else {
		map->buckets[bucket_idx] = entry->next;
	}

	if (value) {
		*value = entry->value;
	}

	put_free_entry(map, entry);

	SYS_HASH_MAP_UNLOCK(map);

	return 0;
}

void *sys_hash_map_get(struct sys_hash_map *map, uint64_t key)
{
	uint32_t hash = hash_func(key);
	uint32_t bucket_idx = hash & (map->n_buckets - 1);
	struct sys_hash_map_entry *entry;

	SYS_HASH_MAP_LOCK(map);

	entry = map->buckets[bucket_idx];

	while (entry) {
		if (entry->key == key) {
			break;
		}
		entry = entry->next;
	}

	SYS_HASH_MAP_UNLOCK(map);

	return entry ? entry->value : NULL;
}

void sys_hash_map_foreach(struct sys_hash_map *map,
			  sys_hash_map_callback_t cb, void *user_data)
{
	SYS_HASH_MAP_LOCK(map);

	for (uint32_t i = 0; i < map->n_buckets; i++) {
		struct sys_hash_map_entry *entry = map->buckets[i];

		while (entry) {
			cb(entry->key, entry->value, user_data);
			entry = entry->next;
		}
	}

	SYS_HASH_MAP_UNLOCK(map);
}

void sys_hash_map_clear(struct sys_hash_map *map,
			    sys_hash_map_clear_callback_t cb, void *user_data)
{
	SYS_HASH_MAP_LOCK(map);

	for (uint32_t i = 0; i < map->n_buckets; i++) {
		struct sys_hash_map_entry *entry = map->buckets[i];

		while (entry) {
			struct sys_hash_map_entry *next = entry->next;

			if (cb) {
				cb(entry->key, entry->value, user_data);
			}
			put_free_entry(map, entry);
			entry = next;
		}
		map->buckets[i] = NULL;
	}

	SYS_HASH_MAP_UNLOCK(map);
}
